// The two stand-in images the upstream runner serves at /docs/assets/images/walk.gif and tie.webp (see docs-images.json):
// they are real animations (two or more frames, parsed from the files), small, served with the content type of their
// extension, generated by a script that is in the repository, and served by exact name only.
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { existsSync, readFileSync } from 'node:fs';
import { test } from 'node:test';
import { CONTENT_TYPES, DOCS_IMAGE_DIRECTORY, docsImage, docsImages, serveDocsImage } from './docs-images.mjs';
import { readGif, readWebp } from './image-info.mjs';

const MAX_BYTES = 8 * 1024;
const raw = JSON.parse(readFileSync(new URL('./docs-images.json', import.meta.url), 'utf8'));
const sha256 = bytes => createHash('sha256').update(bytes).digest('hex');

test('docs images: exactly the two names Shoelace\'s animated image test requests, each stored as plain base64 text', () => {
  assert.deepEqual(Object.keys(raw.images).sort(), ['tie.webp', 'walk.gif']);
  assert.deepEqual(Object.keys(docsImages).sort(), ['tie.webp', 'walk.gif']);
  for (const [name, entry] of Object.entries(raw.images)) {
    assert.deepEqual(Object.keys(entry), ['base64'], name); // the content type is never stored: it comes from the extension
    assert.match(entry.base64, /^[A-Za-z0-9+/]+={0,2}$/, name);
    assert.equal(docsImages[name].bytes.toString('base64'), entry.base64, name);
  }
});

test('docs images: each is at most 8 KB, and pinned by size and SHA-256', () => {
  const pins = { 'walk.gif': [567, 'e296f83bf917d6e4742e64089b8463d9ba597fe228fa0083529ba67a7971f908'], 'tie.webp': [690, '40118d82e43f343589c73bc1f7601256fde4b71e64817ec861b56ed37e6b2af6'] };
  for (const [name, { bytes }] of Object.entries(docsImages)) {
    assert.ok(bytes.length > 0 && bytes.length <= MAX_BYTES, `${name} is ${bytes.length} bytes`);
    assert.deepEqual([bytes.length, sha256(bytes)], pins[name], name);
  }
});

test('docs images: each is really animated (at least two frames), parsed from the file, and loops forever', () => {
  const gif = readGif(docsImages['walk.gif'].bytes);
  assert.ok(gif.frames >= 2, `${gif.frames} GIF frames`);
  assert.deepEqual(gif, { width: 96, height: 72, frames: 3, loops: 0, delays: [25, 25, 25] });
  const webp = readWebp(docsImages['tie.webp'].bytes);
  assert.ok(webp.animated, 'the WebP animation flag');
  assert.ok(webp.frames.length >= 2, `${webp.frames.length} WebP frames`);
  assert.deepEqual(webp, { width: 96, height: 72, animated: true, loops: 0, frames: [['VP8L', 300], ['VP8L', 300], ['VP8L', 300]] });
  // The frames differ: the three image payloads are not the same bytes.
  const frameBytes = new Set();
  const file = docsImages['tie.webp'].bytes;
  for (let at = 12; at + 8 <= file.length;) {
    const size = file.readUInt32LE(at + 4);
    if (file.toString('latin1', at, at + 4) === 'ANMF') frameBytes.add(file.subarray(at + 8 + 16, at + 8 + size).toString('base64'));
    at += 8 + size + (size & 1);
  }
  assert.equal(frameBytes.size, 3);
});

test('docs images: the content type follows the extension (image/gif, image/webp) and is set on what is served', () => {
  assert.deepEqual({ ...CONTENT_TYPES }, { '.gif': 'image/gif', '.webp': 'image/webp' });
  assert.equal(docsImages['walk.gif'].type, 'image/gif');
  assert.equal(docsImages['tie.webp'].type, 'image/webp');
  assert.equal(docsImages['walk.gif'].bytes.toString('latin1', 0, 6), 'GIF89a');
  assert.equal(docsImages['tie.webp'].bytes.toString('latin1', 8, 12), 'WEBP');
  for (const [name, image] of Object.entries(docsImages)) {
    const ctx = { path: `${DOCS_IMAGE_DIRECTORY}${name}` };
    assert.equal(serveDocsImage(ctx), true, name);
    assert.equal(ctx.type, image.type);
    assert.equal(ctx.body, image.bytes);
  }
});

test('docs images: the files are made by a script in the repository, and the file\'s note says so; nothing of Shoelace\'s is copied', () => {
  assert.ok(existsSync(new URL('./make-docs-images.mjs', import.meta.url)));
  assert.match(raw.note, /generated by tests\/upstream\/make-docs-images\.mjs/);
  assert.match(raw.note, /no copied Shoelace file/);
  const script = readFileSync(new URL('./make-docs-images.mjs', import.meta.url), 'utf8');
  assert.match(script, /nothing is copied from Shoelace/);
  assert.match(script, /--check/);
});

// Paths that must not be served: nothing is decoded, normalized or joined to a file system path.
const NOT_SERVED = [
  '/docs/assets/images/unknown.gif',
  '/docs/assets/images/sprite.svg.gif',
  '/docs/assets/images/walk.gif.',
  '/docs/assets/images/walk.gif/',
  '/docs/assets/images/walk.gif/extra',
  '/docs/assets/images/walk.gif?x',
  '/docs/assets/images/Walk.gif',
  '/docs/assets/images/WALK.GIF',
  '/docs/assets/images/tie.WEBP',
  '/docs/assets/images/',
  '/docs/assets/images',
  '/docs/assets/images/.',
  '/docs/assets/images/..',
  '/docs/assets/images/../walk.gif',
  '/docs/assets/images/../images/walk.gif',
  '/docs/assets/images/sub/../walk.gif',
  '/docs/assets/images/./walk.gif',
  '/docs/assets/images/%2e%2e/walk.gif',
  '/docs/assets/images/..%2fwalk.gif',
  '/docs/assets/images/%2e%2e%2fwalk.gif',
  '/docs/assets/images/walk%2egif',
  '/docs/assets/images/%77alk.gif',
  '/docs/assets/images/..\\walk.gif',
  '/docs/assets/images\\walk.gif',
  '/docs/assets/images//walk.gif',
  ['', '', 'docs', 'assets', 'images', 'walk.gif'].join('/'), // a protocol-relative path (written in parts: the privacy scan rejects the literal)
  '/docs/assets/images/walk.gif%00',
  '/docs/assets/images/walk.gif\0',
  '/docs/assets/images/ walk.gif',
  '/docs/assets/images/toString',
  '/docs/assets/images/__proto__',
  '/docs/assets/images/constructor',
  '/docs/assets/images/hasOwnProperty',
  '/docs/assets/walk.gif',
  '/docs/images/walk.gif',
  '/assets/images/walk.gif',
  '/walk.gif',
  '/packages/docs/public/assets/images/walk.gif',
  '/docs/../docs/assets/images/walk.gif',
  ['', 'etc', 'passwd'].join('/'),
  '/docs/assets/images/../../../../etc/passwd',
  'docs/assets/images/walk.gif',
  '',
  undefined,
  null,
  {},
];

test('docs images: an unknown name and any traversal attempt are not served and the context is left untouched', () => {
  for (const path of NOT_SERVED) {
    assert.equal(docsImage(path), undefined, String(path));
    const ctx = { path };
    assert.equal(serveDocsImage(ctx), false, String(path));
    assert.deepEqual(ctx, { path }, `${String(path)} touched the context`);
  }
});

test('docs images: the runner middleware serves the two names and falls through (calls next, serves nothing) for everything else', async () => {
  const { default: config } = await import('./web-test-runner.config.mjs');
  assert.equal(config.middleware.length, 1);
  const [middleware] = config.middleware;
  for (const [name, image] of Object.entries(docsImages)) {
    const ctx = { path: `${DOCS_IMAGE_DIRECTORY}${name}`, url: `${DOCS_IMAGE_DIRECTORY}${name}` };
    let called = false;
    await middleware(ctx, async () => { called = true; });
    assert.equal(called, false, `${name}: the image is served, not passed on`);
    assert.equal(ctx.type, image.type);
    assert.deepEqual(ctx.body, image.bytes);
  }
  for (const path of NOT_SERVED.filter(p => typeof p === 'string')) {
    const ctx = { path, url: path };
    let called = false;
    await middleware(ctx, async () => { called = true; });
    assert.equal(called, true, `${path} falls through`);
    assert.equal(ctx.body, undefined, `${path} was served`);
    assert.equal(ctx.type, undefined, `${path} got a type`);
    assert.equal(ctx.url, path, `${path} was rewritten`);
  }
  // The one other rewrite the middleware keeps: the icon sprite sheet, to the docs site's own file, and it is passed on.
  const sprite = { path: '/docs/assets/images/sprite.svg', url: '/docs/assets/images/sprite.svg' };
  let passed = false;
  await middleware(sprite, async () => { passed = true; });
  assert.equal(passed, true);
  assert.equal(sprite.url, '/packages/docs/public/assets/images/sprite.svg');
  assert.equal(sprite.body, undefined);
});
